const CACHE='pfi-volume-1.1.0-cloudflare-1';
const FILES=['./','./index.html','./style.css','./app.js','./models.js','./inventory.js','./inventory-core.js','./io.js','./offline.js','./pfi-logo.png','./manifest.webmanifest','./icon.svg','./guide.html'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(FILES.map(path=>new Request(new URL(path,self.registration.scope),{cache:'reload'})));})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('pfi-volume-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data==='ACTIVATE')self.skipWaiting();if(event.data==='STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE),ready=(await Promise.all(FILES.map(path=>cache.match(new URL(path,self.registration.scope).href)))).every(Boolean);event.ports[0]?.postMessage({ready,version:'1.1'});})());});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;event.respondWith((async()=>{const cached=await caches.match(event.request,{ignoreSearch:true});if(cached)return cached;try{return await fetch(event.request);}catch(e){if(event.request.mode==='navigate'){const index=await caches.match(new URL('./index.html',self.registration.scope));if(index)return index;}throw e;}})());});
